-- LAKERS TICKETS (Eli, 2026-10-01; mock docs/design-refs/lakers-topclients-options.html).
-- Replaces the "Lakers Tickets Log" spreadsheet: one row per game, who got the pair,
-- who was offered and passed, and Eli's two ticks (claimed on his account / claimed
-- by the recipient). Seeded with all three seasons from the workbook (23-24, 24-25,
-- 25-26 incl. the two Houston playoff games). Dropped from the sheet: TV, and the
-- Potential / Accepted columns (Potential was a running wish-list, not per game).
-- "N/A" recipients (23-24 road preseason) and "Postponed" become blank + a note.
-- Eli + owners only (RLS: role owner).
-- Idempotent: unique (season, game_date, opponent); re-running inserts nothing new.

begin;

create table if not exists public.lakers_games (
  id             uuid primary key default gen_random_uuid(),
  season         text not null,
  game_date      date not null,
  game_time      text,
  opponent       text not null,
  arena          text,
  recipient      text,
  company        text,
  passed         text[] not null default '{}',
  claimed_mine   boolean not null default false,
  claimed_theirs boolean not null default false,
  note           text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  unique (season, game_date, opponent)
);

on conflict (season, game_date, opponent) do nothing;

alter table public.lakers_games enable row level security;
drop policy if exists "lakers_games_owner" on public.lakers_games;
create policy "lakers_games_owner" on public.lakers_games
  for all to authenticated
  using (get_my_role() = 'owner')
  with check (get_my_role() = 'owner');
grant select, insert, update, delete on public.lakers_games to authenticated;
grant all on public.lakers_games to service_role;

commit;

select season, count(*) as games from public.lakers_games group by season order by season;
